package main

import "fmt"

func main() {
	ch := make(chan int, 2)
	ch <- 8
	ch <- 9
	close(ch)
	for v := range ch {
		fmt.Println(v)
	}
}

package main

import "fmt"

func main() {
	ch := make(chan int)
	fmt.Println(cap(ch))
}

package main

import "fmt"

func main() {
	ch := make(chan int, 1)
	ch <- 10
	close(ch)
	for v := range ch {
		fmt.Println(v)
	}
}

package main

import "fmt"

func main() {
	ch := make(chan int, 1)
	select {
	case ch <- 1:
		fmt.Println(2)
	}
}

package main

import "fmt"

func main() {
	ch := make(chan int)
	select {
	case <-ch:
		fmt.Println(1)
	default:
		fmt.Println(7)
	}
}

package main

import "fmt"

func main() {
	ch := make(chan int, 1)
	close(ch)
	for range ch {
		fmt.Println(9)
	}
	fmt.Println(1)
}
